const plainPostKey='slice-plain-posts-v1';
function safePostMedia(m){return m&&['image','video'].includes(m.type)&&typeof m.src==='string'&&(m.type==='image'?/^data:image\/(png|jpeg|webp);base64,/.test(m.src):/^data:video\/(mp4|webm);base64,/.test(m.src)||!!safeLink(m.src))}
const storedPlainPosts=readStored(plainPostKey,[]);if(Array.isArray(storedPlainPosts))works.unshift(...storedPlainPosts.filter(w=>w&&/^post-[a-z0-9-]+$/.test(w.id)&&typeof w.title==='string'&&typeof w.desc==='string'&&typeof w.author==='string'&&Array.isArray(w.media)&&w.media.every(safePostMedia)).map(w=>({...w,plainPost:true,local:true,cat:'Fun & Social',likes:0,plays:'0',bg:'#f1ece3'})));
function plainMediaHTML(media){return media.map(m=>m.type==='video'?`<video controls playsinline preload="metadata" src="${escapeHtml(m.src)}" aria-label="帖子视频"></video>`:`<img src="${escapeHtml(m.src)}" alt="帖子配图" loading="lazy">`).join('')}
const postStageBefore=stage;stage=function(w){if(!w.plainPost)return postStageBefore(w);return w.media.length?`<div class="slice plain-media">${plainMediaHTML(w.media)}</div>`:`<div class="slice plain-text-note"><span>一点日常 / ${escapeHtml(w.author)}</span><p>${escapeHtml(w.desc.slice(0,160))}</p></div>`};
const postDialog=document.createElement('dialog');postDialog.id='plain-post-dialog';postDialog.setAttribute('aria-labelledby','plain-post-heading');postDialog.innerHTML=`<div class="dialog-head"><span>LIFE, AS IT IS</span><button id="close-plain-post" aria-label="关闭图文视频发布">✕</button></div><h2 id="plain-post-heading">不用设计互动，也值得分享。</h2><p class="post-intro">发一段文字、一组照片，或一段视频。</p><form id="plain-post-form"><label>标题<input name="title" maxlength="80" required placeholder="给这个瞬间起个名字"></label><label>正文<textarea name="body" rows="5" maxlength="3000" required placeholder="想说的话，慢慢写…"></textarea></label><label>Slicer 名称<input name="author" maxlength="40" value="我" required></label><label class="post-file-label">添加图片 / 视频<input id="plain-post-file" type="file" multiple accept="image/png,image/jpeg,image/webp,video/mp4,video/webm"></label><small>最多 4 张图片或 1 个视频，合计不超过 2 MB；也可以只发文字。</small><label>或粘贴公开视频直链<input name="videoURL" type="url" placeholder="https://…/video.mp4"></label><small>支持浏览器可播放的 HTTPS 视频文件地址，不是平台视频页面。外链可见性取决于原站。</small><div id="plain-post-media-preview"></div><button type="button" id="clear-post-media" hidden>移除附件</button><p id="plain-post-status" role="status"></p><p class="post-local-note">本机原型：帖子与文件保存在当前浏览器，其他人暂不可见。无需设置互动，也无需发布后续动态。</p><button type="submit" class="dark" id="publish-plain-post">发布到本机首页 ↗</button></form>`;document.body.append(postDialog);
let plainMedia=[],postFileRevision=0,postFileReading=false;const plainForm=postDialog.querySelector('form');
function openPlainPost(){publishDialog.close();postDialog.showModal()}
const plainMode=document.createElement('button');plainMode.type='button';plainMode.className='plain-post-entry';plainMode.innerHTML='<strong>▧ 图文 / 视频</strong><span>分享日常，不需要互动</span>';modes.prepend(plainMode);publishDialog.querySelector('h2+p').textContent='发一篇图文或视频，描述一个互动想法，或上传你的项目。';modes.classList.remove('two-modes');modes.classList.add('three-modes');plainMode.onclick=openPlainPost;
document.querySelector('#close-plain-post').onclick=()=>postDialog.close();
document.querySelector('#plain-post-file').onchange=async e=>{const revision=++postFileRevision,files=[...e.target.files];if(!files.length)return;const status=document.querySelector('#plain-post-status');try{const video=files.some(f=>f.type.startsWith('video/'));if(files.length>4||(video&&files.length!==1))throw Error('请选择最多 4 张图片，或单独 1 个视频。');if(files.some(f=>!['image/png','image/jpeg','image/webp','video/mp4','video/webm'].includes(f.type)))throw Error('支持 JPG、PNG、WebP、MP4、WebM。');if(files.reduce((n,f)=>n+f.size,0)>2*1024*1024)throw Error('本机附件合计最大 2 MB。较大的视频可填写公开视频直链。');postFileReading=true;status.textContent='正在读取附件…';const media=await Promise.all(files.map(f=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve({type:f.type.startsWith('video/')?'video':'image',src:reader.result});reader.onerror=()=>reject(Error('文件读取失败，请重试。'));reader.readAsDataURL(f)})));if(revision!==postFileRevision)return;plainMedia=media;plainForm.elements.videoURL.value='';document.querySelector('#plain-post-media-preview').innerHTML=plainMediaHTML(media);document.querySelector('#clear-post-media').hidden=false;status.textContent='附件已就绪'}catch(err){status.textContent=err.message}finally{if(revision===postFileRevision)postFileReading=false}};
document.querySelector('#clear-post-media').onclick=()=>{postFileRevision++;postFileReading=false;plainMedia=[];document.querySelector('#plain-post-file').value='';document.querySelector('#plain-post-media-preview').innerHTML='';document.querySelector('#clear-post-media').hidden=true;document.querySelector('#plain-post-status').textContent='已移除附件'};
plainForm.onsubmit=e=>{e.preventDefault();const title=plainForm.elements.title.value.trim(),body=plainForm.elements.body.value.trim(),author=plainForm.elements.author.value.trim(),url=plainForm.elements.videoURL.value.trim(),status=document.querySelector('#plain-post-status');if(postFileReading){status.textContent='附件仍在读取，请稍候。';return}if(!title||!body||!author){status.textContent='请填写标题、正文和 Slicer 名称。';return}if(url&&!safeLink(url)){status.textContent='请填写有效的 HTTPS 视频文件地址。';return}if(url&&plainMedia.length){status.textContent='请在附件与视频直链中选择一种，先移除附件或清空链接。';return}const media=url?[{type:'video',src:url}]:plainMedia;const w={id:'post-'+crypto.randomUUID(),title,desc:body,author,cat:'Fun & Social',time:media.some(m=>m.type==='video')?'视频日记':media.length?'图文日记':'文字日记',plainPost:true,local:true,likes:0,plays:'0',bg:'#f1ece3',media};try{localStorage.setItem(plainPostKey,JSON.stringify([w,...works.filter(x=>x.plainPost)]))}catch{status.textContent='浏览器空间不足，帖子未发布。请减少附件大小后重试。';return}works.unshift(w);selected='All';document.querySelectorAll('[data-cat]').forEach(b=>{b.classList.toggle('selected',b.dataset.cat==='All');b.setAttribute('aria-pressed',String(b.dataset.cat==='All'))});featuredRow.hidden=false;document.querySelector('.feature').hidden=false;document.querySelector('.queue-entry').hidden=false;render();postDialog.close();plainForm.reset();document.querySelector('#clear-post-media').onclick();location.hash='discover';openWork(w.id);toast('已发布图文 / 视频帖子到本机')};
const postRenderBefore=render;render=function(){postRenderBefore();works.filter(w=>w.plainPost||w.lifeType).forEach(w=>{const card=document.querySelector('#card-'+w.id);if(!card)return;card.querySelector('.delivery-badge').textContent=w.plainPost?'生活分享 · 本机帖子':'生活手记 · 虚构示例';card.querySelector('[data-open]').textContent='读全文 ↗';card.querySelector('[data-remix]').textContent='写一篇';})};
const postOpenBefore=openWork;openWork=function(id,remix=false){const w=works.find(x=>x.id===id);if(remix&&(w?.plainPost||w?.lifeType||w?.daily)){openPlainPost();return}postOpenBefore(id,remix);if(w?.plainPost&&!remix){document.querySelector('#dialog-mode').textContent=w.time+' · 本机帖子';document.querySelector('#dialog-desc').textContent=w.desc;document.querySelector('#dialog-desc').style.whiteSpace='pre-line';document.querySelector('#full-work-panel')?.remove();document.querySelector('#slice-updates').remove();arrangeDetailCards()}};
render();if(location.hash.startsWith('#work=')){const id=location.hash.slice(6);if(works.some(w=>w.id===id))openWork(id)}
